-- 73 Spirograph: wire figures turning, and a pen tracing the large one
-- with a trail. Every edge is thin and turning - what stair-steps without
-- anti-aliasing; the scene's `fxaa` post effect blends the stairs, and F
-- switches it (PostProcess.set_enabled). Generated by tools/gen_scenes.py.

script = { tick_rate = 60 }

local nav = require("nav")
local SCENE = "scenes/73-spirograph.scene"
local SPINS = { { "Rose", 0.05 }, { "Tide", -0.12 }, { "Iris", 0.09 }, { "Fern", 0.1 }, { "Ember", -0.08 } }
local CX, CY, R, r, d, S = 0.0, 10.0, 96, 36, 60, 1.75
local captions, aa = true, true
local figures, pen, status = {}, nil, nil
local t, u = 0, 0

function init(entity)
    for i, f in ipairs(SPINS) do figures[i] = { e = Entity.find_by_name(f[1]), spin = f[2] } end
    pen = Entity.find_by_name("Pen")
    status = Entity.find_by_name("Status")
end

function update(entity, dt)
    nav.tick(SCENE)
    if Input.is_key_just_pressed("Tab") then captions = nav.toggle_ui_captions(captions) end
    if Input.is_key_just_pressed("F") then
        aa = not aa
        PostProcess.set_enabled("fxaa", aa)
    end
    t = t + dt
    for _, f in ipairs(figures) do
        if f.e then Transform.set_rotation(f.e, t * f.spin) end
    end
    -- The pen runs along the large figure, turning with it.
    u = u + dt * 1.6
    local x = (R - r) * math.cos(u) + d * math.cos((R - r) / r * u)
    local y = (R - r) * math.sin(u) - d * math.sin((R - r) / r * u)
    local a = t * figures[1].spin
    local px, py = (x * math.cos(a) - y * math.sin(a)) * S, (x * math.sin(a) + y * math.cos(a)) * S
    if pen then Transform.set_position(pen, CX + px, CY + py) end
    if status then UI.set_text(status, "anti-aliasing " .. (aa and "on (fxaa)" or "off")) end
end
